parameters.jsCode:
// Get current item from AI node
const item = $json;

// Get original merged data from 2 nodes back
const mergeData = $('Merge').item.json;

// ── Extract AI text ───────────────────────────────────────────────────────
let raw = '';
if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
  raw = item.candidates[0].content.parts[0].text;
} else if (item.message?.content) {
  raw = item.message.content;
} else if (item.text) {
  raw = item.text;
}

// ── Clean and parse JSON ──────────────────────────────────────────────────
const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch (e1) {
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    try {
      parsed = JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
    } catch (e2) {
      parsed = {
        match_score: 0,
        matchedSkills: [],
        missingSkills: [],
        recommendation: 'review',
        reason: 'Could not parse AI response',
      };
    }
  }
}

// ── Pull candidate + job from Merge node ──────────────────────────────────
const candidateId = mergeData.candidate_id;
const candidateScore = mergeData.input1?.overall_score || mergeData.overall_score || '';
const candidateName = mergeData.input1?.name || mergeData.name || '';
const candidateEmail = mergeData.input1?.email || mergeData.email || '';
const candidateStatus = mergeData.input1?.status || mergeData.status || '';

const jobId = mergeData.jobId || '';
const jobTitle = mergeData.title || '';

// ── Return final result ───────────────────────────────────────────────────
return {
  json: {
    // AI scores
    matchScore: parsed.match_score ?? 0,
    matchedSkills: parsed.matchedSkills ?? [],
    missingSkills: parsed.missingSkills ?? [],
    recommendation: parsed.recommendation ?? 'review',
    reason: parsed.reason ?? '',
    improve: parsed.improve ?? '',

    // ── Enhanced match data ──
    matchScoreBreakdown: parsed.scoreBreakdown ?? null,
    matchExperienceSummary: parsed.experience_summary ?? '',
    matchTotalExperienceYears: parsed.total_experience_years ?? 0,
    matchStrengths: parsed.strengths ?? [],
    matchConcerns: parsed.concerns ?? [],
    matchHiringSignal: parsed.hiring_signal ?? '',
    matchOneLineVerdict: parsed.one_line_verdict ?? '',
    matchInterviewQuestions: parsed.interview_questions ?? [],
    matchFlaggedManipulation: parsed.flagged_manipulation ?? false,

    // Candidate info
    candidate_id: candidateId,
    overall_score: candidateScore,
    name: parsed.extracted_name || candidateName, 
    email: parsed.extracted_email || candidateEmail,
    phone: parsed.extracted_phone || '',
    status: candidateStatus,
    experience: parsed.total_experience_years ?? mergeData.experience ?? 0,

    // Job info
    job_id: jobId,
    job_title: jobTitle,
    processed_at: new Date().toISOString(),
  }
};

